GET /api/projects/be8bf71d-4ceb-4115-9cf6-22dfd12f37b6 200 in 50ms :: {"id":"be8bf71d-4ceb-4115-9cf6-22dfd12f37b6","userId":null,"inventorsUserId":"798f403b-6ff0-4ad2-a245-c3228c7e171f","title":"testetest","category":null,"currentStage":5,"currentSubstage":"4b","completed":0,"sourceCodeFiles":[{"id":"code-1781809699981-vdpvi41","code":"// --- Recursive Priority Decomposition Engine ---

interface Task {
  id: string;
  tenantId: string;
  ownerId: string;
  assigneeId: string;
  dimensions: Record<string, number>; // e.g. { urgency: 0.7, importance: 0.4 }
  metadata: Record<string, unknown>;
}

interface MatrixCell {
  coordinates: Record<string, number>; // which cell in the matrix
  tasks: Task[];
}

interface DecompositionResult {
  orderedTasks: Task[];
  recursionDepth: number;
  delegationActions: DelegationAction[];
}

interface DelegationAction {
  taskId: string;
  fromActorId: string;
  toActorId: string;
  triggerCell: Record<string, number>;
}

interface TenantConfig {
  dimensions: string[];
  cellResolutionThreshold: number; // max tasks per cell before recursion
  maxRecursionDepth: number;
  matrixGeometry: Record<string, number>; // bins per dimension
  delegationRules: DelegationRule[];
}

interface DelegationRule {
  cellPattern: Record<string, number>; // which cell coordinates trigger delegation
  reassignmentStrategy: string; // e.g. "round_robin", "least_loaded", "manager"
}

function decompose(
  tasks: Task[],
  config: TenantConfig,
  depth: number = 0
): DecompositionResult {
  if (tasks.length <= config.cellResolutionThreshold || depth >= config.maxRecursionDepth) {
    return { orderedTasks: tasks, recursionDepth: depth, delegationActions: [] };
  }

  // Re-normalize axes to local min/max of this cohort
  const normalizedTasks = renormalizeAxes(tasks, config.dimensions);

  // Plot onto fresh matrix
  const cells = plotToMatrix(normalizedTasks, config.matrixGeometry);

