GET /api/projects 200 in 89ms :: [{"id":"bfdac485-4145-49d4-a62f-26d1ddebce35","userId":null,"inventorsUserId":"798f403b-6ff0-4ad2-a245-c3228c7e171f","title":"chrome extension","category":null,"currentStage":4,"currentSubstage":"4a","completed":0,"sourceCodeFiles":[{"id":"code-1779196709323-acr7y2t","code":"interface Entity {
    value: string;
    action: 'tokenize' | 'ignore';
}

class PayloadInterceptor {
    private tokenMap = new Map<string, string>();

    interceptOutbound(payload: string, detectedEntities: Entity[]): string {
        let sanitizedPayload = payload;

        // Fix #2: sort longest-first so "John Smith" is replaced before "John"
        const toTokenize = detectedEntities
            .filter(e => e.action === 'tokenize')
            .sort((a, b) => b.value.length - a.value.length);

        toTokenize.forEach(entity => {
            const token = `{{TOKEN_${crypto.randomUUID()}}}`;
            this.tokenMap.set(token, entity.value);
            // Fix #1: split/join replaces ALL occurrences, not just the first
            sanitizedPayload = sanitizedPayload.split(entity.value).join(token);
        });

        return sanitizedPayload;
    }

    rehydrateInbound(responsePayload: string): string {
        let restored = responsePayload;

        this.tokenMap.forEach((originalValue, token) => {
            // Fix #4: case-insensitive match so the LLM can mangle UUID casing
            // without breaking rehydration. Token chars still escaped for safety.
            const escaped = token.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            const pattern = new RegExp(escaped, 'gi');
            restored = restored.replace(pattern, originalValue);
        });

        // Fix #3: clear the map — one instance = one round trip
        this.tokenMap.clear();
        return restored;
    }

    // Optional: explicit reset if you need to abort a round trip mid-flight
    reset(): void {
        this…

